from pathlib import Path
import re, json, statistics, math
from collections import defaultdict, Counter
root=Path('/home/lijian/project/Obsidian/vault')
exclude_dirs={'.git','.obsidian','Assets','Templates'}
exclude_names={'README.md'}

def read(p):
    return p.read_text(encoding='utf-8', errors='ignore')

def strip_frontmatter(s):
    if s.startswith('---'):
        parts=s.split('---',2)
        if len(parts)>=3:
            return parts[2]
    return s

def content_units(text):
    return len(re.findall(r'[一-鿿]', text)) + len(re.findall(r'[A-Za-z0-9_]+', text))

def headings(text):
    hs=[]
    for line in text.splitlines():
        m=re.match(r'^(#{1,4})\s+(.+?)\s*$', line)
        if m:
            title=m.group(2).strip()
            if title and not title.startswith('!'):
                hs.append((len(m.group(1)), title[:80]))
    return hs

def maybe_title(p, text):
    # first H1 else filename
    for lvl,h in headings(text):
        if lvl==1:
            return h
    return p.stem

rows=[]
for p in sorted(root.rglob('*.md')):
    rel=p.relative_to(root)
    if any(part in exclude_dirs for part in rel.parts) or p.name in exclude_names:
        continue
    text=strip_frontmatter(read(p))
    units=content_units(text)
    hs=headings(text)
    h2=sum(1 for lvl,_ in hs if lvl==2)
    h3=sum(1 for lvl,_ in hs if lvl==3)
    code_blocks=text.count('```')//2
    top=rel.parts[0] if len(rel.parts)>1 else '<root>'
    sub=rel.parts[1] if len(rel.parts)>2 else ''
    # classify directness
    name=p.stem.lower()
    direct=True
    reason=''
    if p.stem.startswith('MOC-') or 'MOC-' in p.stem or '索引' in p.stem or '汇总' in p.stem or '报告' in p.stem:
        direct=False; reason='hub/index/report'
    if units < 250:
        direct=False; reason=(reason+'; ' if reason else '')+'too_short'
    # style suitability: technical source vs meta/vault docs
    suitability='high'
    if top in ['00-Inbox','01-Projects','03-Resources','04-Archives']:
        suitability='medium'
    if 'content' in rel.parts or 'learning' in rel.parts:
        suitability='medium'
    # estimate scripts: headings and units, conservative for hub/index
    base=0
    if units>=250:
        base=max(1, min(12, round(units/1800)))
        if h2>=3:
            base=max(base, min(12, 1 + h2//2))
        if code_blocks>=2:
            base=max(base, min(12, base+1))
        if not direct:
            base=max(1, min(base, 2))
        if suitability=='medium':
            base=max(1, math.floor(base*0.8))
    low=max(0, math.floor(base*0.6))
    mid=base
    high=max(mid, math.ceil(base*1.5))
    rows.append({
        'rel':str(rel),'top':top,'sub':sub,'title':maybe_title(p,text),'units':units,'h2':h2,'h3':h3,'code':code_blocks,'direct':direct,'suitability':suitability,'est_low':low,'est_mid':mid,'est_high':high,
        'headings':[h for lvl,h in hs if lvl<=3][:8]
    })

# aggregate by area path under 02-Areas/xxx plus other
agg=defaultdict(lambda: {'notes':0,'units':0,'low':0,'mid':0,'high':0,'direct':0})
for r in rows:
    if r['top']=='02-Areas':
        key='02-Areas/'+(r['sub'] or '<root>')
    else:
        key=r['top']
    a=agg[key]
    a['notes']+=1; a['units']+=r['units']; a['low']+=r['est_low']; a['mid']+=r['est_mid']; a['high']+=r['est_high']; a['direct']+=int(r['direct'])
print('TOTAL_ROWS', len(rows))
print('AGGREGATES')
for k,a in sorted(agg.items(), key=lambda kv:(-kv[1]['mid'], kv[0])):
    print(json.dumps({'area':k, **a}, ensure_ascii=False))
print('\nTOP_NOTES_BY_EST')
for r in sorted(rows, key=lambda x:(-x['est_mid'],-x['units']))[:40]:
    print(json.dumps({k:r[k] for k in ['rel','title','units','h2','code','est_low','est_mid','est_high','headings']}, ensure_ascii=False))
